async ({ workspace: { search, glob }, git: { status, log }, shell: { execFile } }) => {
  const [files, s, l, rel, tags] = await Promise.all([
    glob(["*.md", "docs/*.md", ".github/workflows/*"]),
    status(["--short", "--branch"]),
    execFile("git", ["log", "--oneline", "-5", "origin/main"]),
    search("release", { glob: "{AGENTS.md,CONTRIBUTING.md,docs/releas*.md,RELEASING.md}", limit: 40, contextLines: 1 }),
    execFile("git", ["tag", "--sort=-v:refname"]),
  ]);
  return { files: files.entries, s, l: l.stdout, rel, tags: tags.stdout.split("\n").slice(0, 3) };
}
